CREATE OR REPLACE FUNCTION public.traffic_can_read_file(_file uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'traffic') AND EXISTS(SELECT 1 FROM public.creative_versions v JOIN public.creative_reviews r ON r.version_id=v.id WHERE v.file_id=_file AND r.decision='Aprovado' AND NOT EXISTS(SELECT 1 FROM public.creative_reviews newer WHERE newer.version_id=r.version_id AND (newer.created_at,newer.id)>(r.created_at,r.id))) $$;
REVOKE ALL ON FUNCTION public.traffic_can_read_file(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.traffic_can_read_file(uuid) TO authenticated;
ALTER POLICY files_extra_read ON public.files USING((spy_id IS NOT NULL AND public.is_member()) OR profile_id=auth.uid() OR public.traffic_can_read_file(id));
CREATE OR REPLACE FUNCTION public.valid_final_file(_file uuid,_item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.files f JOIN storage.objects o ON o.name=f.path AND o.bucket_id='dr-files' WHERE f.id=_file AND f.item_id=_item AND f.purpose='final' AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items i WHERE i.id=_item AND i.assigned_to=auth.uid() AND public.has_role(auth.uid(),'editor')))) $$;
REVOKE ALL ON FUNCTION public.valid_final_file(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.valid_final_file(uuid,uuid) TO authenticated;
ALTER POLICY versions_insert ON public.creative_versions WITH CHECK(created_by=auth.uid() AND public.valid_final_file(file_id,item_id));